// the coroutine carries the details, not the thread
class Customer(val name: String) : AbstractCoroutineContextElement(Customer) {
    companion object Key : CoroutineContext.Key<Customer>
}

suspend fun checkout(order: Order): Receipt = withContext(Customer(order.customer)) {   // bound for this block
    val bank = async { theBank.approve(order) }
    val line = async { receiptLine(order.item) }        // children inherit the context
    Receipt(line.await(), bank.await())
}

suspend fun receiptLine(item: String): String =
    item + " for " + (currentCoroutineContext()[Customer]?.name ?: error("no customer"))

