Receipt checkout(Order order) throws InterruptedException {
    try (var scope = StructuredTaskScope.open()) {                  // default: fail on the first failure
        Subtask<Approval> bank = scope.fork(() -> theBank.approve(order));
        Subtask<Stock> stock = scope.fork(() -> stockService.check(order));
        scope.join();                                               // throws if a subtask failed
        return new Receipt(stock.get(), bank.get());                // get() only after join()
    }                                                               // close() waits for every subtask
}

// a caller on JDK 25
try {
    return checkout(order);
} catch (StructuredTaskScope.FailedException e) {     // unchecked; the cause is the subtask's exception
    throw new CheckoutFailedException(e.getCause());
}
// on JDK 27 and later, join() throws the checked ExecutionException instead:
// } catch (ExecutionException e) { throw new CheckoutFailedException(e.getCause()); }

